import{_ as r,C as a,o as n,c as l,a6 as o,E as s}from"./chunks/framework.BJFjZBwW.js";const b=JSON.parse('{"title":"(Option 1) Upload from the web","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"upload/web-install.md","filePath":"upload/web-install.md","lastUpdated":1785770623000}'),i={name:"upload/web-install.md"};function d(h,e,c,p,u,f){const t=a("BoardEnvironmentTable");return n(),l("div",null,[e[0]||(e[0]=o('<h1 id="option-1-upload-from-the-web" tabindex="-1">(Option 1) Upload from the web <a class="header-anchor" href="#option-1-upload-from-the-web" aria-label="Permalink to &quot;(Option 1) Upload from the web&quot;">​</a></h1><p>This is the easiest way to install OpenMQTTGateway: no software to download, no development environment.</p><h2 id="before-you-flash" tabindex="-1">Before you flash <a class="header-anchor" href="#before-you-flash" aria-label="Permalink to &quot;Before you flash&quot;">​</a></h2><ul><li>Use a <strong>data</strong> USB cable — many cables are charge-only and the board won&#39;t show up with one.</li><li>Use <strong>Chrome, Edge or Opera</strong> — Firefox and Safari don&#39;t support web flashing.</li><li>Most boards need a <strong>USB serial driver</strong>. Recent operating systems often include it; if your board doesn&#39;t appear in the port list, see below.</li></ul><details class="details custom-block"><summary>My board doesn&#39;t show up in the port list</summary><ol><li>Try another USB cable (data, not charge-only) and another USB port.</li><li>Install the driver matching your board&#39;s USB chip (check the board&#39;s product page if unsure): <ul><li><strong>CP210x</strong> (Silicon Labs): <a href="https://www.silabs.com/developer-tools/usb-to-uart-bridge-vcp-drivers" target="_blank" rel="noreferrer">driver download</a></li><li><strong>CH340 / CH341</strong> (WCH): <a href="https://www.wch-ic.com/downloads/CH341SER_ZIP.html" target="_blank" rel="noreferrer">driver download</a></li><li><strong>CH9102</strong> (WCH): <a href="https://github.com/WCHSoftGroup/ch34xser_macos" target="_blank" rel="noreferrer">macOS driver</a>, <a href="https://www.wch-ic.com/downloads/CH343SER_ZIP.html" target="_blank" rel="noreferrer">Windows driver</a></li></ul></li><li>On macOS, complete the driver installation by confirming it in the <strong>Security</strong> section of <strong>System Preferences</strong>, then restart. For a LilyGo LoRa32 V2.1 board, the correct port to select is <code>/dev/cu.wchusbserialXXXXXXXXXXX</code>.</li><li>Some boards need the <strong>BOOT</strong> button held down while plugging in the cable to enter flash mode.</li><li>On Linux, add your user to the <code>dialout</code> group (<code>sudo usermod -a -G dialout $USER</code>) and log in again.</li></ol></details><h2 id="select-your-firmware" tabindex="-1">Select your firmware <a class="header-anchor" href="#select-your-firmware" aria-label="Permalink to &quot;Select your firmware&quot;">​</a></h2><p>To upload firmware to your ESP device directly from this page, first connect your ESP device to a USB port on your computer. Then, choose the appropriate firmware from the available options. Next, click the <strong>Connect</strong> button and select the USB port where your ESP is plugged in. Wait for the upload process to finish. After the upload completes, you can set up your <a href="./portal.html">WiFi and MQTT credentials</a>.</p>',7)),s(t,{boardsUrl:"/boards-info.json",selectorPath:"/upload/board-selector.html"}),e[1]||(e[1]=o('<p><small style="color:var(--vp-c-text-3);">Board photos courtesy of their manufacturers. ESP32 Feather photo © <a href="https://www.adafruit.com/product/3405">Adafruit Industries</a>, <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA</a>.</small></p><div class="tip custom-block"><p class="custom-block-title">Running on a tablet or phone</p><p>If you want to use the BLE decoding capabilities of OpenMQTTGateway with a tablet or smartphone you can use <a href="https://app.theengs.io/" target="_blank" rel="noreferrer">Theengs App</a>.</p></div><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p>Once the upload is complete, connect the gateway to your WiFi network and MQTT broker through the <a href="./portal.html">configuration portal</a>.</p>',4))])}const g=r(i,[["render",d]]);export{b as __pageData,g as default};
